VALUES (81005, 'tt1351685', NULL, 'Jack the Giant Slayer', 'Jack the Giant Slayer', 'movie', 2013, 'https://image.tmdb.org/t/p/w500/9jSI7saUX9Qz0JLh19jX2ulEwL7.jpg', 'https://image.tmdb.org/t/p/original/djSAd6HUm66eVNC3PiZbYwOpD5A.jpg', 'The story of an ancient war that is reignited when a young farmhand unwittingly opens a gateway between our world and a fearsome race of giants. Unleashed on the Earth for the first time in centuries, the giants strive to reclaim the land they once lost, forcing the young man, Jack into the battle of his life to stop them. Fighting for a kingdom, its people, and the love of a brave princess, he comes face to face with the unstoppable warriors he thought only existed in legend–and gets the chance to become a legend himself.', NULL, NULL, 12.9023, 5.918, 0, 2.01, '2026-07-20 01:02:04', '2026-10-20 05:01:58')
