VALUES (83533, 'tt1757678', NULL, 'Avatar: Fire and Ash', 'Avatar: Fire and Ash', 'movie', 2025, 'https://image.tmdb.org/t/p/w500/bRBeSHfGHwkEpImlhxPmOcUsaeg.jpg', 'https://image.tmdb.org/t/p/original/sdZSjtGUTSN8B3al5o0f2WoQfQQ.jpg', 'In the wake of the devastating war against the RDA and the loss of their eldest son, Jake Sully and Neytiri face a new threat on Pandora: the Ash People, a violent and power-hungry Na''vi tribe led by the ruthless Varang. Jake''s family must fight for their survival and the future of Pandora in a conflict that pushes them to their emotional and physical limits.', NULL, NULL, 99.9449, 7.634, 0, 9.25571428571428533e+00, '2026-07-31 03:33:23', '2026-10-20 05:01:58')
