VALUES (616037, 'tt10648342', NULL, 'Thor: Love and Thunder', 'Thor: Love and Thunder', 'movie', 2022, 'https://image.tmdb.org/t/p/w500/pIkRyD18kl4FhoCNQuWxWu5cBLM.jpg', 'https://image.tmdb.org/t/p/original/jsoz1HlxczSuTx0mDl2h0lxy36l.jpg', 'After his retirement is interrupted by Gorr the God Butcher, a galactic killer who seeks the extinction of the gods, Thor Odinson enlists the help of King Valkyrie, Korg, and ex-girlfriend Jane Foster, who now wields Mjolnir as the Mighty Thor. Together they embark upon a harrowing cosmic adventure to uncover the mystery of the God Butcher’s vengeance and stop him before it’s too late.', NULL, NULL, 30.4035, 6.352, 0, 6.05, '2026-10-19 04:56:39', '2026-10-20 05:01:58')
